function selectProgram(id){state.program=id;state.day=0;save();render()}function selectDay(i){state.day=i;save();render()}function start(){unlock();requestWakeLock();if(!state.draft){const d=day();if(!d.ex.length)return alert('Add exercises first');let legacy=state.program==='original'?state.legacyDraft[state.day]:null;state.draft={id:uid(),name:d.name,program:state.program,day:state.day,started:Date.now(),clock:{elapsed:0,since:Date.now()},ex:d.ex.map((e,i)=>({...clone(e),logged:Object.values(legacy?.[i]?.sets||{}).filter(valid)}))};if(state.program==='original')delete state.legacyDraft[state.day];index=0;save()}go('active')}/* V6.4 Smart Load and Coach. Old kg records are always treated as recorded total; no migration rewrite. */
